-- READ ONLY: examine migration state and permissions without returning user rows.
select table_name from information_schema.tables where table_schema='public' and table_name in ('profiles','exercises','equipment','workout_sessions','workout_exercises','workout_sets','meal_entries','meal_photos','import_batches','import_previews') order by table_name;
select c.relname as table_name,c.relrowsecurity as rls_enabled from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('profiles','exercises','equipment','workout_sessions','workout_exercises','workout_sets','meal_entries','meal_photos','import_batches','import_previews') order by c.relname;
select schemaname,tablename,policyname,roles,cmd,qual,with_check from pg_policies where (schemaname='public' and tablename in ('profiles','exercises','equipment','workout_sessions','workout_exercises','workout_sets','meal_entries','meal_photos','import_batches','import_previews')) or (schemaname='storage' and tablename='objects') order by schemaname,tablename,policyname;
select table_name,grantee,privilege_type from information_schema.role_table_grants where table_schema='public' and table_name in ('profiles','exercises','equipment','workout_sessions','workout_exercises','workout_sets','meal_entries','meal_photos','import_batches','import_previews') and grantee in ('PUBLIC','anon','authenticated') order by table_name,grantee,privilege_type;
select id,public,file_size_limit,allowed_mime_types from storage.buckets where id='meal-photos';
select to_regclass('fitness_journal_meta.migrations') as migration_registry;
